    @Test
    public void newUrlBuilderWithNullInputUrlIsValid() throws Exception {
        UrlBuilder builder = new UrlBuilder(null);
        assertNotEquals(null, builder.inputUrl);
    }

    @Test
    public void buildUrlFromInvalidInputUrlThrowsException() throws Exception {
        UrlBuilder builder = new UrlBuilder();
        try {
            builder.build();
            assert false;
        } catch (Exception e) {
            assert true;
        }
    }

    @Test
    public void appendKeyValToUrl() throws Exception {
        String inputUrl = "http://example.com";
        String key1 = "value1";
        String key2 = "value2";

        UrlBuilder builder = new UrlBuilder(inputUrl);

        builder.appendKeyVal(key1, key2);
        assertEquals("http://example.com?key1=value1", builder.inputUrl);

        builder.appendKeyVal(key2, key3);
        assertEquals("http://example.com?key1=value1&key2=value2", builder.inputUrl);
    }

    @Test
    public void toStringMethod() {
        String inputUrl = "http://example.com";

        UrlBuilder builder = new UrlBuilder(inputUrl);

        StringBuilder expectedUrl = new StringBuilder(inputUrl);
        expectedUrl.append("?key1=value1");

        assertEquals(expectedUrl.toString(), builder.inputUrl());
    }

    public static class UrlBuilder {

        private String inputUrl;

        public UrlBuilder(String inputUrl) {
            this.inputUrl = inputUrl;
        }

        public void appendKeyVal(String key, String value) {
            if (inputUrl.contains("?")) {
                inputUrl += "&" + key + "=" + value;
            } else {
                inputUrl += "?" + key + "=" + value;
            }
        }

        public String inputUrl() {
            return inputUrl;
        }

        @Override
        public String toString() {
            return inputUrl;
        }
    }
}
